const form=document.querySelector('#reservation'),status=document.querySelector('#status'),select=document.querySelector('#service');let services=[],requestId=crypto.randomUUID();
form.oninput=()=>requestId=crypto.randomUUID();
function quote(){const s=services.find(s=>s.id===select.value);document.querySelector('#quote').textContent=s?`Service: ₦${s.price.toLocaleString()} · Pay ${s.deposit_percent}% now: ₦${(Math.ceil(s.price*100*s.deposit_percent/100)/100).toLocaleString()}. Any remaining balance is due at the studio.`:'';}
fetch('/api/services').then(async r=>{const data=await r.json();if(!r.ok)throw new Error(data.error);services=data;select.replaceChildren(...services.map(s=>new Option(s.name,s.id)));quote();if(!services.length)throw new Error('Services are being configured. Please book through WhatsApp.');return fetch('/api/health');}).then(r=>r.json()).then(health=>{if(!health.bookingEnabled)throw new Error('Online payment booking is being set up. Please use WhatsApp for now.');form.querySelector('button').disabled=false;}).catch(e=>status.textContent=e.message);select.onchange=quote;
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;status.textContent='Preparing your booking and secure checkout…';try{const b=Object.fromEntries(new FormData(form));b.at=b.date+'T'+b.time+':00+01:00';b.requestId=requestId;const r=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),result=await r.json();if(!r.ok)throw new Error(result.error);location.assign(result.url);}catch(e){status.textContent=e.message;button.disabled=false;}};
